import XCTest
import AppKit
import SwiftUI
@testable import BurnFuseUI

/// Guards the mark: the tile stays deep graphite, the filament lands green at
/// one end and red at the other, and it is visibly *broken* — the burnt half
/// sprung above the tail rather than a straight unbroken bar.
///
/// The Dock icon, the README header and the sidebar mark are all this same view,
/// so this is the only automated proof the icon renders at all: assets are
/// regenerated by hand, but a mark that stopped drawing would fail here first.
@MainActor
final class FuseMarkTests: XCTestCase {

    private func pixels(of view: some View, side: CGFloat) throws -> NSBitmapImageRep {
        let hosting = NSHostingView(rootView: view)
        hosting.layoutSubtreeIfNeeded()
        hosting.frame = NSRect(x: 0, y: 0, width: side, height: side)
        hosting.layoutSubtreeIfNeeded()
        let rep = try XCTUnwrap(hosting.bitmapImageRepForCachingDisplay(in: hosting.bounds))
        hosting.cacheDisplay(in: hosting.bounds, to: rep)
        rep.size = NSSize(width: side, height: side)
        return rep
    }

    /// Perceived lightness — the filament is far brighter than any surface it
    /// sits on, which is what every check below keys off.
    private func lightness(_ c: NSColor) -> Double {
        0.2126 * Double(c.redComponent) + 0.7152 * Double(c.greenComponent) + 0.0722 * Double(c.blueComponent)
    }

    /// How far a pixel leans green — positive when green leads the other
    /// channels, which is what the tail of the filament should do.
    private func greenLean(_ c: NSColor) -> Double {
        Double(c.greenComponent) - max(Double(c.redComponent), Double(c.blueComponent))
    }

    /// How far a pixel leans red — the burnt end's colour.
    private func redLean(_ c: NSColor) -> Double {
        Double(c.redComponent) - max(Double(c.greenComponent), Double(c.blueComponent))
    }

    /// The tile is a surface, not a gradient logo: dark, and neutral where the
    /// filament is not.
    func testTheTileStaysGraphite() throws {
        let side: CGFloat = 256
        let rep = try pixels(of: FuseMark(size: side), side: side)
        let inset = Int(Double(rep.pixelsWide) * 0.10)
        let corner = try XCTUnwrap(rep.colorAt(x: inset, y: inset))
        XCTAssertLessThan(lightness(corner), 0.45, "the tile should be deep graphite")
        XCTAssertLessThan(abs(corner.redComponent - corner.blueComponent), 0.25,
                          "the tile should be neutral, not tinted")
    }

    /// Calm at the tail, hot at the broken end: the app's own three colours, on
    /// the one filament.
    func testTheFilamentRunsCalmToHot() throws {
        let side: CGFloat = 256
        let rep = try pixels(of: FuseMark(size: side), side: side)

        var greenest = 0.0
        var reddest = 0.0
        for y in 0..<rep.pixelsHigh {
            for x in 0..<rep.pixelsWide {
                guard let c = rep.colorAt(x: x, y: y) else { continue }
                if Double(x) < Double(rep.pixelsWide) * 0.45 { greenest = max(greenest, greenLean(c)) }
                if Double(x) > Double(rep.pixelsWide) * 0.55 { reddest = max(reddest, redLean(c)) }
            }
        }
        XCTAssertGreaterThan(greenest, 0.15, "the tail of the filament should be visibly green")
        XCTAssertGreaterThan(reddest, 0.15, "the burnt end should be visibly red")
    }

    /// The break: the burnt half is drawn above the tail and offset from it, so
    /// the mark is a filament that gave way rather than a progress bar.
    func testTheFilamentBreaksAndSprings() throws {
        let side: CGFloat = 512
        let rep = try pixels(of: FuseMark(size: side), side: side)
        let scale = Double(rep.pixelsWide) / Double(side)

        /// Where the filament sits in each column, found as the brightest thing
        /// in it — the wire and its glow are far brighter than the tile.
        func wireHeight(from: Double, to: Double) -> Double? {
            var heights: [Double] = []
            for x in Int(Double(rep.pixelsWide) * from)..<Int(Double(rep.pixelsWide) * to) {
                var best = 0.0
                var at: Double?
                for y in 0..<rep.pixelsHigh {
                    guard let c = rep.colorAt(x: x, y: y) else { continue }
                    let l = lightness(c)
                    if l > best { best = l; at = Double(y) }
                }
                if let at, best > 0.5 { heights.append(at) }
            }
            guard !heights.isEmpty else { return nil }
            return heights.reduce(0, +) / Double(heights.count)
        }

        let tail = try XCTUnwrap(wireHeight(from: 0.10, to: 0.40), "no filament in the left half")
        let burnt = try XCTUnwrap(wireHeight(from: 0.70, to: 0.90), "no filament in the right half")
        XCTAssertGreaterThan(tail - burnt, 8 * scale,
                             "the burnt half should sit above the tail — the mark is a break, not a bar")
    }

    /// The gap has to survive being drawn at the size the app actually uses in
    /// its own sidebar and menu-bar panel.
    func testTheMarkStillReadsAtSidebarSize() throws {
        let side: CGFloat = 18
        let rep = try pixels(of: FuseMark(size: side), side: side)

        var greenest = 0.0
        var reddest = 0.0
        var lit = 0
        for y in 0..<rep.pixelsHigh {
            for x in 0..<rep.pixelsWide {
                guard let c = rep.colorAt(x: x, y: y) else { continue }
                if lightness(c) > 0.5 { lit += 1 }
                if Double(x) < Double(rep.pixelsWide) * 0.45 { greenest = max(greenest, greenLean(c)) }
                if Double(x) > Double(rep.pixelsWide) * 0.55 { reddest = max(reddest, redLean(c)) }
            }
        }
        XCTAssertGreaterThan(lit, 4, "the filament should still be lit at 18pt")
        XCTAssertGreaterThan(greenest, 0.05, "the tail should still read green at 18pt")
        XCTAssertGreaterThan(reddest, 0.05, "the burnt end should still read red at 18pt")
    }

    /// Bare mode is the filament on someone else's dark ground — no tile. Drawn
    /// here over black, which is the only case it is for.
    func testBareGroundDrawsOnlyTheFilament() throws {
        let side: CGFloat = 256
        let bare = FuseMark(size: side, ground: .bare)
            .frame(width: side, height: side)
            .background(Color.black)
        let rep = try pixels(of: bare, side: side)
        let inset = Int(Double(rep.pixelsWide) * 0.10)
        let corner = try XCTUnwrap(rep.colorAt(x: inset, y: inset))
        XCTAssertLessThan(lightness(corner), 0.12, "bare mode should draw no tile")
    }
}
